48	    static void cpvs2points(const cpVect* verts, Vec2* outPoints, int count);
49	
50	    static Vec2 getBodyPosition(cpBody* body);
51	    static float getBodyAngle(cpBody* body);
52	    static cpTransform transform2cpTransform(const Vec2& pos, float angle);
53	    static int computeConvexHull(const Vec2* points, int count, Vec2* outHull);
54	    static Vec2 computePolygonCenter(const Vec2* verts, int count);
55	    static bool isPolygonConvex(const Vec2* verts, int count);
56	    static bool segmentIntersect(const Vec2& a1, const Vec2& a2, const Vec2& b1, const Vec2& b2, Vec2* intersection);
57	    static float pointToSegmentDistance(const Vec2& point, const Vec2& segA, const Vec2& segB);
58	    static float polygonArea(const Vec2* verts, int count);
59	    static float polygonMoment(float mass, const Vec2* verts, int count, const Vec2& offset);
60	    static float circleArea(float radius);
61	    static float circleMoment(float mass, float radius, const Vec2& offset);
62	};
